head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    //  ※ setPosition 의 mode(absolute/relative) 동작을 관측하려면 대상이 positioned 여야 하므로
    //    기본 style 로 position:relative 를 먼저 넣고, style(target) 조건값을 뒤에 붙여
    //    조건이 선택되면 조건값이 우선 적용되도록 한다.
    let cStyle = "position:relative;";
    cStyle += scwin.gVar["cStyle"];
    cStyle += "width:300px; height:200px;"
    let cStyleParent = scwin.gVar["cStyleParent"];

    // parent 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    // createBasicWidgetContainer(고정 style) 대신 widgetContainer 를 직접 생성
    //  (parent1 하위, cStyle=con_style_target 반영 -> setPosition 동작 확인)
    let strTarget = '';
    strTarget += '<w2:widgetContainer ' + strNameSpace + ' mode="" cols="" style="' + cStyle + '"></w2:widgetContainer>';

    // base(common_M)가 objParent.target1 로 접근하므로 target1 id 로 생성 (parent1 하위에 생성)
    scwin.target1 = await $p.dynamicCreate('target1', "widgetContainer", strTarget, parent1);

    // 내용 확인용 Widget 생성 (Widget 이 없으면 컨테이너 내용이 비어 위치 확인이 어렵다)
    let addedWidgets = scwin.target1.addWidgets({
        id: 'widget1',
        title: '위젯01',
        src: '/sample/common_link/widgetContainer_link_1.xml',
        scope: true,
        unitWidth: 1,
        unitHeight: 1
    });
    if (addedWidgets && addedWidgets[0]) {
        addedWidgets[0].setMaximized();
    }
}
